<?php
declare(strict_types=1);
$cc=static fn(string $ar,string $en):string=>($adminLocale??admin_locale())==='en'?$en:$ar;
$campaignStates=['draft'=>$cc('مسودة','Draft'),'scheduled'=>$cc('مجدولة','Scheduled'),'processing'=>$cc('قيد المعالجة','Processing'),'completed'=>$cc('اكتملت المعالجة','Processing complete'),'partially_failed'=>$cc('اكتملت مع أخطاء','Completed with errors'),'cancelled'=>$cc('ملغاة','Cancelled')];
$campaignAudiences=['all_eligible'=>$cc('كل المؤهلين','All eligible users'),'locale'=>$cc('لغة محددة','Selected language'),'scholar_followers'=>$cc('متابعو عالم','Scholar followers'),'series_followers'=>$cc('متابعو سلسلة','Series followers'),'lesson_reminders'=>$cc('مشتركو تذكير درس','Lesson reminder subscribers'),'test_recipient'=>$cc('اختبار المالك عبر Push','Owner Push test')];
$campaignEditing=$campaignPreview['campaign']??null;
$campaignForm=$campaignEditing??['id'=>'','revision'=>'','name'=>'','channel'=>'push','audience_type'=>'all_eligible','audience_ref_id'=>'','audience_locale'=>'','title_ar'=>'','body_ar'=>'','title_en'=>'','body_en'=>'','deep_link'=>'','image_url'=>'','scheduled_at'=>'','schedule_timezone'=>'UTC','ttl_seconds'=>86400,'min_frequency_hours'=>6,'respect_quiet_hours'=>true];
$campaignCanEdit=!$campaignEditing||($campaignEditing['status']==='draft'&&(($admin['role']??'')==='owner'||(int)$campaignEditing['created_by']===(int)$admin['id']));
$campaignForm['scheduled_at']=$campaignForm['scheduled_at']!==''&&$campaignForm['scheduled_at']!==null?(new DateTimeImmutable($campaignForm['scheduled_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone($campaignForm['schedule_timezone']))->format('Y-m-d\TH:i:s'):'';
$campaignForm['schedule_offset']=$campaignEditing&&!empty($campaignEditing['scheduled_at'])?(new DateTimeImmutable($campaignEditing['scheduled_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone($campaignEditing['schedule_timezone']))->format('P'):'';
$campaignForm['ttl_hours']=(int)$campaignForm['ttl_seconds']/3600;
$campaignStale=false;
if($adminError!==''&&($_POST['kind']??'')==='engagement-campaign-save') {
    $campaignStale=$campaignEditing&&(string)$campaignEditing['revision']!==(string)($_POST['expected_revision']??'');
    foreach(['name','channel','audience_type','audience_ref_id','audience_locale','title_ar','body_ar','title_en','body_en','deep_link','image_url','scheduled_at','schedule_timezone','schedule_offset','ttl_hours','min_frequency_hours'] as $field)if(is_string($_POST[$field]??null))$campaignForm[$field]=mb_substr($_POST[$field],0,1200,'UTF-8');
    $campaignForm['revision']=is_string($_POST['expected_revision']??null)?$_POST['expected_revision']:$campaignForm['revision'];$campaignForm['respect_quiet_hours']=isset($_POST['respect_quiet_hours']);
}
?>
