    <div class="section-heading"><div><span class="eyebrow"><?= e($cc('التواصل باحترام','Thoughtful communication')) ?></span><h2><?= e($cc('الحملات','Campaigns')) ?></h2></div><span class="source-chip"><?= (int)$campaignPageData['pagination']['total'] ?> <?= e($cc('حملة','campaigns')) ?></span></div>
    <p class="source-note"><?= e($cc('المسودة لا ترسل رسائل. الجمهور يعتمد على الموافقة واللغة والمتابعات الصريحة فقط، دون سجل عبادة شخصي. الإطلاق يتطلب تأكيد المالك، والتسليم الفعلي يعتمد على جاهزية القنوات.','Drafts send no messages. Audiences use consent, language and explicit follows, with no personal worship history. Launch requires Owner confirmation and ready delivery channels.')) ?></p>
    <?php if($campaignUnavailable): ?><div class="notice notice-error"><?= e($cc('الحملات غير متاحة حاليًا لهذا الحساب أو أن إعدادها لم يكتمل.','Campaigns are currently unavailable for this account or their setup is incomplete.')) ?></div><?php else: ?>
    <?php if($campaignCanEdit): ?><article class="knowledge-card admin-campaign-composer"><h3><?= e($campaignEditing?$cc('تعديل المسودة','Edit draft'):$cc('مسودة جديدة','New draft')) ?></h3>
        <?php if($campaignStale): ?><p class="notice notice-error"><?= e($cc('هذه النسخة قديمة. احتُفظ بالنص، وأوقف الحفظ حتى إعادة التحميل.','This version is stale. Your text is retained; reload the saved version before changing it.')) ?></p><?php endif; ?>
        <?php if($campaignEditing): ?><a class="button button-secondary" href="/admin?campaign_preview=<?= (int)$campaignEditing['id'] ?>&amp;campaign_reload=<?= (int)$campaignEditing['revision'] ?>#admin-campaigns"><?= e($cc('إعادة تحميل النسخة المحفوظة','Reload saved version')) ?></a><a class="button button-secondary" href="/admin?campaign_new=1#admin-campaigns"><?= e($cc('مسودة جديدة','New draft')) ?></a><?php endif; ?>
        <form method="post" class="form-stack" data-campaign-editor><?= csrf_field() ?><input type="hidden" name="kind" value="engagement-campaign-save"><input type="hidden" name="campaign_id" value="<?= e((string)$campaignForm['id']) ?>"><input type="hidden" name="expected_revision" value="<?= e((string)$campaignForm['revision']) ?>">
            <fieldset <?= $campaignStale?'disabled':'' ?>><legend><?= e($cc('تفاصيل الرسالة والجمهور','Message and audience')) ?></legend>
            <label><?= e($cc('اسم الحملة الداخلي','Internal campaign name')) ?><input name="name" maxlength="160" minlength="2" value="<?= e((string)$campaignForm['name']) ?>" required></label>
            <div class="admin-form-grid"><label><?= e($cc('القناة','Channel')) ?><select name="channel"><?php foreach(['push'=>'Push','email'=>'Email','push_email'=>'Push + Email'] as $value=>$label): ?><option value="<?= e($value) ?>"<?= $campaignForm['channel']===$value?' selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label>
            <label><?= e($cc('الجمهور','Audience')) ?><select name="audience_type"><?php foreach($campaignAudiences as $value=>$label): ?><option value="<?= e($value) ?>"<?= $campaignForm['audience_type']===$value?' selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label>
            <label><?= e($cc('لغة الجمهور','Audience language')) ?><select name="audience_locale"><?php foreach([''=>$cc('الكل','All'),'ar'=>'العربية','en'=>'English'] as $value=>$label): ?><option value="<?= e($value) ?>"<?= $campaignForm['audience_locale']===$value?' selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label>
            <label><?= e($cc('رقم العالم أو السلسلة أو الدرس','Scholar, series or lesson ID')) ?><input type="number" name="audience_ref_id" min="1" value="<?= e((string)$campaignForm['audience_ref_id']) ?>"></label></div>
            <div class="admin-form-grid"><?php foreach(['ar'=>'العربية','en'=>'English'] as $language=>$label): ?><div dir="<?= $language==='ar'?'rtl':'ltr' ?>"><label><?= e($cc('العنوان','Title').' · '.$label) ?><input name="title_<?= $language ?>" minlength="2" maxlength="180" value="<?= e((string)$campaignForm['title_'.$language]) ?>" required></label><label><?= e($cc('النص','Message').' · '.$label) ?><textarea name="body_<?= $language ?>" minlength="2" maxlength="1000" rows="5" required><?= e((string)$campaignForm['body_'.$language]) ?></textarea></label></div><?php endforeach; ?></div>
            <div class="admin-form-grid"><?php foreach(['deep_link'=>[$cc('وجهة عامة اختيارية','Optional public destination'),'text',500],'image_url'=>[$cc('صورة HTTPS اختيارية','Optional HTTPS image'),'url',500],'scheduled_at'=>[$cc('الموعد المحلي (فارغ للإطلاق الآن)','Local time (blank for launch now)'),'datetime-local',30],'schedule_timezone'=>[$cc('منطقة زمنية IANA','IANA timezone'),'text',80],'schedule_offset'=>[$cc('فرق UTC عند تكرار الوقت، مثل ‎+02:00','UTC offset for repeated times, e.g. +02:00'),'text',6],'ttl_hours'=>[$cc('الصلاحية بالساعات (1–168)','Lifetime in hours (1–168)'),'number',3],'min_frequency_hours'=>[$cc('الفاصل بالساعات (1–168)','Minimum interval in hours (1–168)'),'number',3]] as $field=>$spec): ?><label><?= e($spec[0]) ?><input name="<?= e($field) ?>" type="<?= e($spec[1]) ?>" maxlength="<?= $spec[2] ?>" dir="ltr" value="<?= e((string)$campaignForm[$field]) ?>"<?= $spec[1]==='number'?' min="1" max="168" required':'' ?><?= $field==='scheduled_at'?' step="1"':'' ?>></label><?php endforeach; ?></div>
            <label class="check-label"><input type="checkbox" name="respect_quiet_hours"<?= $campaignForm['respect_quiet_hours']?' checked':'' ?>><?= e($cc('احترام ساعات عدم الإزعاج','Respect quiet hours')) ?></label>
            <button class="button button-primary" type="submit"><?= e($cc('حفظ مسودة فقط','Save draft only')) ?></button></fieldset>
        </form></article><?php endif; ?>
    <?php if($campaignPreview): $cp=$campaignPreview['campaign']; ?><article class="knowledge-card admin-campaign-preview"><h3><?= e($cp['name']) ?> · <?= e($campaignStates[$cp['status']]??$cp['status']) ?></h3><p><?= e($cc('النسخة المحفوظة','Saved version')) ?> <?= (int)$cp['revision'] ?></p>
        <div class="admin-preview-grid"><?php foreach(['ar'=>'العربية','en'=>'English'] as $language=>$label): ?><section dir="<?= $language==='ar'?'rtl':'ltr' ?>"><strong><?= e($label) ?></strong><h4><?= e($cp['title_'.$language]) ?></h4><p><?= nl2br(e($cp['body_'.$language])) ?></p></section><?php endforeach; ?></div>
        <?php foreach($campaignPreview['audience'] as $channel=>$audience): ?><p><?= e(strtoupper($channel)) ?> · <?= (int)$audience['eligible_count'] ?> <?= e($cc('مؤهل حاليًا','currently eligible')) ?><?php if(!$audience['available']): ?> · <?= e($cc('التسليم غير جاهز','Delivery unavailable')) ?> <code><?= e($audience['reason']) ?></code><?php endif; ?></p><?php endforeach; ?>
        <p><?= e($cc('المعاينة الحية قد تتغير حتى التأكيد. بعد التأكيد تُحفظ الرسالة واللغة والجمهور؛ تُراجع الموافقة مجددًا قبل التسليم.','Live eligibility can change before confirmation. Confirmation saves the message, language and audience; consent is checked again before delivery.')) ?></p>
        <div class="admin-campaign-stats"><?php foreach($cp['delivery_counts'] as $state=>$count): ?><span><?= e(['queued'=>$cc('في الطابور','Queued'),'processing'=>$cc('قيد المعالجة','Processing'),'sent'=>$cc('قبلها مزود التسليم','Accepted by provider'),'failed'=>$cc('فشلت','Failed'),'skipped'=>$cc('تُخطيت','Skipped'),'cancelled'=>$cc('أُلغيت','Cancelled'),'total'=>$cc('المجموع','Total')][$state]) ?>: <?= (int)$count ?></span><?php endforeach; ?></div>
        <?php if($cp['status']==='draft'&&($admin['role']??'')==='owner'): ?><form class="form-stack" method="post"><?= csrf_field() ?><input type="hidden" name="kind" value="engagement-campaign-confirm"><input type="hidden" name="campaign_id" value="<?= (int)$cp['id'] ?>"><input type="hidden" name="expected_revision" value="<?= (int)$cp['revision'] ?>"><label><?= e($cc('اكتب العبارة حرفيًا','Type the exact phrase')) ?><input name="confirmation" dir="ltr" placeholder="CONFIRM <?= (int)$cp['id'] ?>" autocomplete="off" required></label><label><?= e($cc('كلمة مرور المالك الحالية','Current Owner password')) ?><input type="password" name="owner_password" autocomplete="current-password" required></label><button class="button button-primary"<?= $campaignStale||$campaignPreview['dependencies']?' disabled':'' ?>><?= e($cc('تأكيد وجدولة','Confirm and schedule')) ?></button></form><?php endif; ?>
        <?php if(in_array($cp['status'],['draft','scheduled','processing'],true)&&(($admin['role']??'')==='owner'||(int)$cp['created_by']===(int)$admin['id'])): ?><form method="post" data-confirm="<?= e($cc('إلغاء ما لم يبدأ تسليمه؟ الرسالة الجاري تسليمها قد تكتمل.','Cancel remaining deliveries? A message already being delivered may complete.')) ?>"><?= csrf_field() ?><input type="hidden" name="kind" value="engagement-campaign-cancel"><input type="hidden" name="campaign_id" value="<?= (int)$cp['id'] ?>"><input type="hidden" name="expected_revision" value="<?= (int)$cp['revision'] ?>"><button class="button button-secondary"<?= $campaignStale?' disabled':'' ?>><?= e($cc('إلغاء الحملة','Cancel campaign')) ?></button></form><?php endif; ?>
        <details><summary><?= e($cc('سجل التشغيل والأسباب المجمعة','Operational history and aggregate reasons')) ?></summary><?php foreach($cp['delivery_analytics']['reasons'] as $reason): ?><p><code><?= e($reason['code']) ?></code> · <?= (int)$reason['count'] ?></p><?php endforeach; ?><?php foreach($cp['history'] as $event): ?><p><?= e($event['event_type']) ?> · <time><?= e($event['created_at']) ?> UTC</time></p><?php endforeach; ?></details>
    </article><?php endif; ?>
