    <nav aria-label="<?= e($cc('صفحات الحملات','Campaign pages')) ?>"><?php if($campaignPageData['pagination']['page']>1): ?><a class="button button-secondary" href="/admin?campaigns_page=<?= $campaignPageData['pagination']['page']-1 ?>#admin-campaigns"><?= e($cc('السابق','Previous')) ?></a><?php endif; ?><?php if($campaignPageData['pagination']['has_more']): ?><a class="button button-secondary" href="/admin?campaigns_page=<?= $campaignPageData['pagination']['page']+1 ?>#admin-campaigns"><?= e($cc('التالي','Next')) ?></a><?php endif; ?></nav>
    <?php endif; ?>
